<?php
/*
Template Name: Upsellio - Blog v4 (Core)
Template Post Type: page
*/
if (!defined('ABSPATH')) { exit; }

$blog_index_url = function_exists('upsellio_get_blog_index_url') ? upsellio_get_blog_index_url() : '';
if (!$blog_index_url) { $blog_index_url = home_url('/blog/'); }
$category = isset($_GET['category']) && is_string($_GET['category']) ? sanitize_title(wp_unslash($_GET['category'])) : '';
if ($category === 'all') { $category = ''; }
$search = isset($_GET['blog_search']) && is_string($_GET['blog_search']) ? sanitize_text_field(wp_unslash($_GET['blog_search'])) : '';
if ($search === '' && isset($_GET['s']) && is_string($_GET['s'])) { $search = sanitize_text_field(wp_unslash($_GET['s'])); }
$tag_input = $_GET['tags'] ?? $_GET['tag'] ?? '';
$tags = function_exists('upsellio_parse_tag_filters') ? upsellio_parse_tag_filters(wp_unslash($tag_input)) : [];
$paged = max(1, (int) get_query_var('paged'), (int) get_query_var('page'), isset($_GET['paged']) ? (int) $_GET['paged'] : 1);
$payload = upsellio_get_blog_payload($category, $tags, $search, $paged);
$blog_query = $payload['blog_query'];
$posts = $blog_query->posts;
$featured = $paged === 1 && $category === '' && $search === '' && !$tags ? array_shift($posts) : null;
$categories = $payload['categories'];
$lead_magnet = function_exists('upsellio_get_primary_lead_magnet') ? upsellio_get_primary_lead_magnet() : [];
$contact_url = function_exists('upsellio_get_contact_page_url') ? upsellio_get_contact_page_url() : home_url('/kontakt/');
$link = static function ($overrides = []) use ($blog_index_url, $category, $tags, $search) {
    return add_query_arg(array_filter(array_merge(['category' => $category, 'tags' => implode(',', $tags), 'blog_search' => $search], $overrides), static function ($value) { return $value !== '' && $value !== null; }), $blog_index_url);
};
$thumb = static function ($id, $size = 'medium_large', $eager = false) {
    if (has_post_thumbnail($id)) {
        return get_the_post_thumbnail($id, $size, ['loading' => $eager ? 'eager' : 'lazy', 'decoding' => 'async']);
    }
    $image = get_post_meta($id, '_upsellio_featured_image_url', true);
    return $image ? '<img src="' . esc_url($image) . '" alt="' . esc_attr(get_the_title($id)) . '" loading="' . ($eager ? 'eager' : 'lazy') . '" decoding="async">' : '<div class="ub-placeholder" aria-hidden="true">Upsellio · Blog</div>';
};
$cat_label = static function ($id) {
    $cats = get_the_category($id);
    return !empty($cats) ? $cats[0]->name : 'Blog';
};
$read = static function ($id) { return function_exists('upsellio_estimated_read_time') ? upsellio_estimated_read_time($id) : ''; };
$teaser = static function ($id, $words) { return wp_trim_words(wp_strip_all_tags(get_the_excerpt($id)), $words, '…'); };
get_header();
?>
