:40px;background:#f5f6f8;border-radius:20px}.ub-pager{display:flex;justify-content:center;flex-wrap:wrap;gap:8px;margin-top:36px}.ub-magnet{padding:0 0 80px}.ub-magnet-card{padding:40px;background:#effaf7;border:1px solid #dff5ef;border-radius:24px;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:24px}.ub-magnet-card>div{flex:1 1 480px}.ub-magnet-card h2{margin:0 0 10px;font-size:clamp(26px,2.8vw,34px)}.ub :is(a,button,input):focus-visible{outline:3px solid #0bb39c;outline-offset:3px}@media(max-width:850px){.ub-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ub-featured{grid-template-columns:1fr}.ub-feature-img{min-height:0;aspect-ratio:16/9}.ub-feature-copy{padding:24px}.ub-hero{padding:48px 0}.ub-search{max-width:none}}@media(max-width:540px){.ub .ub-wrap{padding:0 20px}.ub-grid{grid-template-columns:1fr}.ub-list{padding:40px 0 56px}.ub-magnet-card{padding:24px}.ub-magnet{padding-bottom:56px}.ub-feature-img .ub-placeholder{min-height:0}}@media(prefers-reduced-motion:reduce){.ub-card{transition:none}}
