<form method="get" action="<?php echo esc_url($blog_index_url); ?>" class="ub-search" role="search"><input type="search" name="blog_search" aria-label="Szukaj w blogu" placeholder="Szukaj w blogu" value="<?php echo esc_attr($search); ?>"><?php if ($category !== '') : ?><input type="hidden" name="category" value="<?php echo esc_attr($category); ?>"><?php endif; ?><?php if ($tags) : ?><input type="hidden" name="tags" value="<?php echo esc_attr(implode(',', $tags)); ?>"><?php endif; ?><button type="submit">Szukaj</button></form></div></section>
<?php if ($featured) : $id = (int) $featured->ID; ?>
<section class="ub-feature"><div class="ub-wrap"><article class="ub-featured"><a class="ub-feature-img" href="<?php echo esc_url(get_permalink($id)); ?>" tabindex="-1" aria-hidden="true"><span class="ub-feature-badge">Polecany</span><?php echo $thumb($id, 'large', true); ?></a><div class="ub-feature-copy"><span class="ub-cat"><?php echo esc_html($cat_label($id)); ?></span><h2><a href="<?php echo esc_url(get_permalink($id)); ?>"><?php echo esc_html(get_the_title($id)); ?></a></h2><p><?php echo esc_html($teaser($id, 36)); ?></p><div class="ub-author"><div class="ub-avatar" aria-hidden="true"><?php $name = get_the_author_meta('display_name', (int) $featured->post_author); echo esc_html(function_exists('upsellio_get_initials_from_text') ? upsellio_get_initials_from_text($name) : 'U'); ?></div><div><strong><?php echo esc_html($name); ?></strong><small><?php echo esc_html(get_the_date('j M Y', $id)); ?> · <?php echo esc_html($read($id)); ?></small></div></div><a class="ub-btn" href="<?php echo esc_url(get_permalink($id)); ?>">Czytaj →</a></div></article></div></section>
<?php endif; ?>
<section class="ub-list"><div class="ub-wrap"><div class="ub-list-head"><h2>Najnowsze wpisy</h2><nav class="ub-filters" aria-label="Kategorie bloga"><a href="<?php echo esc_url($link(['category'=>''])); ?>"<?php echo $category === '' ? ' aria-current="page"' : ''; ?>>Wszystkie</a><?php foreach ($categories as $cat) : ?><a href="<?php echo esc_url($link(['category'=>$cat->slug])); ?>"<?php echo $category === $cat->slug ? ' aria-current="page"' : ''; ?>><?php echo esc_html($cat->name); ?></a><?php endforeach; ?></nav></div>
<?php if ($search !== '' || $tags) : ?><p class="ub-filter-note">Aktywne filtry: <?php echo esc_html(trim($search . ' ' . implode(', ', $tags))); ?> · <a href="<?php echo esc_url($blog_index_url); ?>">Wyczyść</a></p><?php endif; ?>
<div class="ub-grid"><?php foreach ($posts as $item) : $id = (int) $item->ID; ?><article class="ub-card"><a class="ub-thumb" href="<?php echo esc_url(get_permalink($id)); ?>" aria-hidden="true" tabindex="-1"><?php echo $thumb($id); ?></a><div class="ub-card-copy"><span class="ub-cat"><?php echo esc_html($cat_label($id)); ?></span><h3><a href="<?php echo esc_url(get_permalink($id)); ?>"><?php echo esc_html(get_the_title($id)); ?></a></h3><p><?php echo esc_html($teaser($id, 23)); ?></p><div class="ub-meta"><?php echo esc_html(get_the_date('j M Y', $id)); ?> · <?php echo esc_html($read($id)); ?></div></div></article><?php endforeach; ?></div>
<?php if (!$posts && !$featured) : ?><div class="ub-empty">Brak wpisów pasujących do wybranych filtrów. <a href="<?php echo esc_url($blog_index_url); ?>">Zobacz wszystkie wpisy.</a></div><?php endif; ?>
<?php if ($blog_query->max_num_pages > 1) : ?><nav class="ub-pager" aria-label="Paginacja bloga"><?php if ($paged > 1) : ?><a href="<?php echo esc_url($link(['paged'=>$paged > 2 ? $paged-1 : null])); ?>">← Nowsze</a><?php endif; ?><?php for ($i=1;$i<=$blog_query->max_num_pages;$i++) : ?><?php if ($i === $paged) : ?><span aria-current="page"><?php echo (int) $i; ?></span><?php else : ?><a href="<?php echo esc_url($link(['paged'=>$i>1?$i:null])); ?>"><?php echo (int) $i; ?></a><?php endif; ?><?php endfor; ?><?php if ($paged < $blog_query->max_num_pages) : ?><a href="<?php echo esc_url($link(['paged'=>$paged+1])); ?>">Starsze →</a><?php endif; ?></nav><?php endif; ?></div></section>
<section class="ub-magnet"><div class="ub-wrap"><div class="ub-magnet-card"><div><div class="ub-eyebrow"><?php echo !empty($lead_magnet['url']) ? 'Materiał do pobrania' : 'Bezpłatna diagnoza'; ?></div><h2><?php echo esc_html(!empty($lead_magnet['title']) ? $lead_magnet['title'] : 'Sprawdźmy, gdzie uciekają Twoi klienci.'); ?></h2><p><?php echo esc_html(!empty($lead_magnet['excerpt']) ? wp_trim_words(wp_strip_all_tags($lead_magnet['excerpt']), 30) : 'Praktyczne wskazówki dla Twojej firmy.'); ?></p></div><a class="ub-btn" href="<?php echo esc_url(!empty($lead_magnet['url']) ? $lead_magnet['url'] : $contact_url); ?>"><?php echo !empty($lead_magnet['url']) ? 'Zobacz materiał' : 'Umów bezpłatną diagnozę'; ?> →</a></div></div></section>
</main>
<?php
$schema_posts = $blog_query->posts;
if ($schema_posts) {
    $schema = ['@context'=>'https://schema.org','@type'=>'Blog','name'=>'Blog Upsellio','url'=>$blog_index_url,'blogPost'=>array_map(static function ($post) { return ['@type'=>'BlogPosting','headline'=>get_the_title($post),'url'=>get_permalink($post),'description'=>wp_strip_all_tags(get_the_excerpt($post)),'datePublished'=>get_the_date('c',$post),'dateModified'=>get_the_modified_date('c',$post),'author'=>['@type'=>'Person','name'=>get_the_author_meta('display_name',(int)$post->post_author)]]; }, $schema_posts)];
    echo '<script type="application/ld+json">' . wp_json_encode($schema, JSON_UNESCAPED_UNICODE | JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) . '</script>';
}
